// Build conversation history for Claude
const history = $input.all().map(item => item.json);
const userMessage = $('Telegram Trigger').item.json.message.text;
const userId = $('Telegram Trigger').item.json.message.from.id;
const userName = $('Telegram Trigger').item.json.message.from.first_name || 'User';

// Format conversation history
let conversationContext = '';
if (history && history.length > 0) {
  conversationContext = history.map(row => {
    return `${row.role}: ${row.message}`;
  }).join('\n');
}

const systemPrompt = `You are LifeSync, a family life assistant for ${userName}. You help manage family schedules, school communications, reminders, and daily coordination.

You have access to these capabilities:
- View and manage Google Calendar events
- Track homework and school communications
- Set reminders
- Query the event log for past events
- Coordinate with family members (Josh is co-parent, Emma is daughter at St. Patrick School)

When the user wants to take an action, respond with BOTH:
1. A friendly conversational response
2. A JSON action block wrapped in <action>{...}</action> tags

Available actions:
- {"type": "add_calendar_event", "title": "...", "date": "YYYY-MM-DD", "time": "HH:MM", "calendar": "personal|family|work|school", "notify": ["josh"]}
- {"type": "set_reminder", "message": "...", "datetime": "YYYY-MM-DDTHH:MM:SS"}
- {"type": "update_calendar_event", "event_id": "...", "updates": {...}}
- {"type": "query_events", "date_range": "today|this_week|this_month", "category": "all|school|work|family"}
- {"type": "mark_homework_done", "subject": "..."}
- {"type": "notify_family", "recipient": "josh", "message": "..."}

If the user is just chatting or asking a question that doesn't need an action, just respond conversationally without an action block.

Today's date is ${new Date().toISOString().split('T')[0]}.`;

const messages = [];

// Add history as messages
if (conversationContext) {
  const historyLines = conversationContext.split('\n');
  for (const line of historyLines) {
    if (line.startsWith('user:')) {
      messages.push({ role: 'user', content: line.replace('user: ', '') });
    } else if (line.startsWith('assistant:')) {
      messages.push({ role: 'assistant', content: line.replace('assistant: ', '') });
    }
  }
}

// Add current message
messages.push({ role: 'user', content: userMessage });

return [{
  json: {
    systemPrompt,
    messages,
    userMessage,
    userId,
    userName
  }
}];

const response = $input.item.json;
const claudeText = response.content[0].text;
const userMessage = $('Build Claude Prompt').item.json.userMessage;
const userId = $('Build Claude Prompt').item.json.userId;

// Extract action if present
let action = null;
let displayText = claudeText;
const actionMatch = claudeText.match(/<action>(.*?)<\/action>/s);
if (actionMatch) {
  try {
    action = JSON.parse(actionMatch[1]);
    displayText = claudeText.replace(/<action>.*?<\/action>/s, '').trim();
  } catch (e) {
    // If JSON parse fails, just send the text
  }
}

return [{
  json: {
    displayText,
    action,
    userMessage,
    userId,
    fullResponse: claudeText
  }
}];

const action = $input.item.json.action;

// Route based on action type
switch(action.type) {
  case 'add_calendar_event':
    return [{ json: { ...action, route: 'calendar' } }];
  case 'update_calendar_event':
    return [{ json: { ...action, route: 'calendar' } }];
  case 'set_reminder':
    return [{ json: { ...action, route: 'reminder' } }];
  case 'query_events':
    return [{ json: { ...action, route: 'query' } }];
  case 'mark_homework_done':
    return [{ json: { ...action, route: 'homework' } }];
  case 'notify_family':
    return [{ json: { ...action, route: 'notify' } }];
  default:
    return [{ json: { ...action, route: 'unknown' } }];
}
